package practice
import("bufio";"errors";"io")
func Export(dst io.WriteCloser, records []string)(err error){
    defer func(){err=errors.Join(err,dst.Close())}()
    writer:=bufio.NewWriterSize(dst,4096)
    for _,record:=range records{
        if _,err=writer.WriteString(record+"\n");err!=nil{return err}
    }
    return writer.Flush()
}
```

底层 Close 不会替外层 bufio.Writer 刷新。先检查写入和 Flush，再关闭目标；命名返回值配合 errors.Join 保留两类错误。实际磁盘文件与注入式 Writer 分别验证字节落入文件和失败传播。没有 fsync 或原子重命名，因此不能据此承诺断电持久性或旧产物保护。

