package practice
import("bytes";"errors";"io";"os";"path/filepath";"strings";"testing")
type sink struct{buffer bytes.Buffer; closed bool; closes,writes,failAfter int; writeErr,closeErr error; short,partial bool; wroteAfterClose bool}
func(s *sink)Write(p []byte)(int,error){
    if s.closed{s.wroteAfterClose=true;return 0,errors.New("write after close")}
    s.writes++
    if s.writeErr!=nil&&(s.failAfter==0||s.buffer.Len()+len(p)>s.failAfter){
        if s.partial{n:=s.failAfter-s.buffer.Len();if n<0{n=0};s.buffer.Write(p[:n]);return n,s.writeErr}
        return 0,s.writeErr
    }
    if s.short{return len(p)/2,nil}
    return s.buffer.Write(p)
}
func(s *sink)Close()error{s.closed=true;s.closes++;return s.closeErr}
func TestExportExactBytes(t *testing.T){
    for _,records:=range [][]string{nil,{""},{"甲","🙂","tail"},{strings.Repeat("x",4095)},{strings.Repeat("y",4096)},{strings.Repeat("z",12289),"tail"},{"a\nb","line\r","nul\x00"}}{
        want:="";for _,v:=range records{want+=v+"\n"}
        s:=&sink{};if err:=Export(s,records);err!=nil{t.Fatal(err)}
        if s.buffer.String()!=want||s.closes!=1||s.wroteAfterClose{t.Fatalf("bytes or lifecycle: want %d got %d closes %d",len(want),s.buffer.Len(),s.closes)}
        // A real file confirms the bytes exist after the function returns.
        path:=filepath.Join(t.TempDir(),"报告.txt");f,err:=os.Create(path);if err!=nil{t.Fatal(err)}
        if err=Export(f,records);err!=nil{t.Fatal(err)}
        got,err:=os.ReadFile(path);if err!=nil||string(got)!=want{t.Fatal("on-disk data differs",err)}
        if _,err=f.Write([]byte("must be closed"));err==nil{f.Close();t.Fatal("file ownership was not released")}
    }
}
func TestExportErrorsRemainDiscoverable(t *testing.T){
    writeFailure:=errors.New("injected write");closeFailure:=errors.New("injected close")
    for _,n:=range []int{1,4095,4096,9000}{
        for _,failClose:=range []bool{false,true}{
            s:=&sink{writeErr:writeFailure};if failClose{s.closeErr=closeFailure}
            err:=Export(s,[]string{strings.Repeat("a",n),"never complete"})
            if !errors.Is(err,writeFailure)||errors.Is(err,closeFailure)!=failClose||s.closes!=1||s.wroteAfterClose{t.Fatal("lost failure or wrong cleanup",n,err,s.closes)}
        }
    }
    s:=&sink{closeErr:closeFailure};err:=Export(s,[]string{"ok"})
    if !errors.Is(err,closeFailure)||s.buffer.String()!="ok\n"||s.closes!=1{t.Fatal("close failure hidden",err)}
    for _,records:=range [][]string{nil,{"payload"}}{
        s:=&sink{short:true,closeErr:closeFailure};err:=Export(s,records)
        if !errors.Is(err,closeFailure)||s.closes!=1{t.Fatal("close not retained")}
        if len(records)>0&&!errors.Is(err,io.ErrShortWrite){t.Fatal("short write accepted",err)}
    }
    // A writer can accept earlier blocks, then return n>0 and an error.
    // Use a byte budget, not a call count: legal buffer sizes may coalesce writes.
    for _,partial:=range []bool{false,true}{
        s:=&sink{writeErr:writeFailure,closeErr:closeFailure,failAfter:5501,partial:partial}
        err:=Export(s,[]string{strings.Repeat("first",1100),strings.Repeat("second",1000),"tail"})
        if !errors.Is(err,writeFailure)||!errors.Is(err,closeFailure)||s.closes!=1||s.wroteAfterClose{t.Fatal("later write failure was lost",err,s.writes,s.closes)}
    }
}
